function ModelCatalogFilter({ modelCount, resetKey, onFilterChange }) {
  const [draft, setDraft] = useState("");
  const debounceRef = useRef(null);

  useEffect(() => {
    setDraft("");
    onFilterChange("");
  }, [onFilterChange, resetKey]);

  useEffect(() => () => clearTimeout(debounceRef.current), []);

  const handleChange = event => {
    const nextValue = event.target.value;
    setDraft(nextValue);
    clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => onFilterChange(nextValue), 90);
  };

  return (
    <input
      type="search"
      value={draft}
      onChange={handleChange}
      onKeyDown={event => event.stopPropagation()}
      placeholder={`Search ${modelCount} models`}
      autoCapitalize="none"
      autoCorrect="off"
      spellCheck={false}
    />
  );
}

// System Prompt guiding the local LLM on drawing tools
const SYSTEM_PROMPT = `You are "Underscores", an autonomous, high-performance drawing assistant.
You drive a collaborative sketchboard (Excalidraw) programmatically through registered Underscores commands. The current action catalog is appended to your context.

CRITICAL: You MUST write your text explanation FIRST, then output any tool XML tags.

Do not emit a bare undefined or null as a response placeholder. After an action tag, continue with a short human-readable summary.

The preferred action protocol is <underscores-command id="stable.id">JSON</underscores-command>. A fenced JSON compatibility envelope must be {"action":"stable.id","payload":{...}}; do not flatten arguments beside action.

When a user asks to explain, expand, beautify, or modify code, show the explanation and formatted code in Markdown first. A selected object with a "codeHost" field is code-capable even when its Excalidraw type is "rectangle"; inspect its elementId, kind, source, parameters, runtime, and other fields before deciding it is a plain shape. If the selected host is legacy p5 or Play Core, use livecode.node.update and keep the same elementId; Underscores will migrate that host in place. The command payload must be valid JSON: encode source with JSON.stringify semantics (\\n for newlines, \\\" for quotes, and \\\\ for backslashes). Never put raw multiline source or unescaped double quotes inside a command JSON string. Use @selection or @livecode context when the user asks about a specific node, and @score for the transport.

Use high-level <underscores-command> tags for all new work. Legacy drawing XML tags remain available only for compatibility:
1. Draw Rectangle:
   <rect x="[coord]" y="[coord]" w="[width]" h="[height]" color="[hex_color]" fill="[hex_color/transparent]"/>
2. Draw Circle/Ellipse:
   <circle x="[center_x]" y="[center_y]" r="[radius]" color="[hex_color]" fill="[hex_color/transparent]"/>
3. Draw Straight Line:
   <line x1="[start_x]" y1="[start_y]" x2="[end_x]" y2="[end_y]" color="[hex_color]"/>
4. Draw Freehand Path:
   <path points="x1,y1 x2,y2 x3,y3 ..." color="[hex_color]"/>
5. Erase Element by ID:
   <erase id="[element_id]"/>
6. Clear Entire Canvas:
   <clear/>
7. Execute a registered Underscores command:
   <underscores-command id="[stable_command_id]">{"argument":"value"}</underscores-command>

Guidelines:
- All shapes should be sized logically (typical screen coords range from 0 to 1000).
- If the user selected a shape or path, you will receive its coordinates in the context. Use this context to duplicate, resize, move, or offset the shape.
- Create objects with scene.create.objects and modify them with scene.patch.objects; use score.roles.assign for score roles.
- Create and edit scripts through the relevant livecode.node.*, script.brush.*, and script.iannix.* commands. Create interactive p5 canvas frames through p5.frame.create. p5 supports instance mode (p.setup, p.draw, and p.* calls) and classic global mode (function setup(), function draw(), and ordinary p5 calls); set mode: "global" for classic source, or omit it for safe auto-detection. Change application settings only through the exposed settings/grid/transport commands.
- @param is an authored source annotation, not a runtime command. Declare it as a line comment such as // @param maxlines = 100 (1..500, step: 1) and read it in trusted p5, Play Core, or Strudel code as __.params.maxlines. There is no implicit global parameters object. The parameters field of livecode.node.update only overrides a value for a declaration already present in the source; it does not expose a new control. When asked to expose a parameter, include the annotation and the __.params use in the source update.
- Never claim that a parameter was exposed unless the updated source visibly contains both the // @param declaration and a matching __.params.<name> read. An empty parameters: {} object does not create a parameter; omit it unless setting a non-default value for an existing declaration.
- Keep your conversational text responses extremely concise and to the point.
`;

// Keep the assistant's scene context semantic without dumping the entire
// Excalidraw customData object. A Livecode node is stored on a transparent
// rectangle host, so geometry alone is not enough to identify it. Older p5
// and Play Core hosts are included as code-capable objects as well; this lets
// the assistant inspect and migrate them instead of describing them as plain
// shapes.
const codeHostContextForElement = element => {
  if (!element || element.isDeleted) return null;
  const customData = element.customData && typeof element.customData === "object" ? element.customData : {};
  const label = customData.label
    || customData.underscoresLabel
    || getScoreData(element)?.label
    || "";
  const geometry = {
    elementId: element.id,
    elementType: element.type,
    x: Math.round(element.x || 0),
    y: Math.round(element.y || 0),
    width: Math.round(element.width || 0),
    height: Math.round(element.height || 0),
  };

  if (isLivecodeNodeElement(element)) {
    const node = normalizeLivecodeNode(customData.underscoresLivecode);
    return {
      ...geometry,
      hostType: "livecode",
      nodeId: node.nodeId,
      kind: node.kind,
      name: node.name,
      ...(label ? { label } : {}),
      source: node.source,
      parameters: node.parameters,
      view: node.view,
      runtime: {
        running: node.runtime.running,
        enabled: node.runtime.enabled,
        transportMode: node.runtime.transportMode,
        settings: node.runtime.settings,
      },
      revision: node.revision,
    };
  }

  if (isP5FrameElement(element)) {
    const frame = normalizeP5Frame(customData.underscoresP5);
    return {
      ...geometry,
      hostType: "p5-legacy",
      kind: LIVECODE_KINDS.p5,
      name: label || frame.scriptId || "p5 frame",
      ...(label ? { label } : {}),
      source: frame.source,
      parameters: frame.parameters,
      runtime: {
        running: frame.autoplay !== false,
        enabled: true,
        transportMode: "linked",
        settings: {
          mode: frame.mode,
          p5Version: frame.p5Version,
          runtime: frame.runtime,
          fps: frame.fps,
          transparent: frame.transparent,
          backgroundMode: frame.backgroundMode,
          persistence: frame.persistence,
          allowInteraction: frame.allowInteraction,
        },
      },
      legacy: true,
      scriptId: frame.scriptId,
    };
  }

  if (isPlayCoreFrameElement(element)) {
    const frame = normalizePlayCoreFrame(customData.underscoresPlayCore);
    return {
      ...geometry,
      hostType: "playcore-legacy",
      kind: LIVECODE_KINDS.playcore,
      name: label || frame.scriptId || "Play Core frame",
      ...(label ? { label } : {}),
      source: frame.source,
      parameters: frame.parameters,
      runtime: {
        running: true,
        enabled: true,
        transportMode: "linked",
        settings: { fps: frame.fps, allowInteraction: frame.allowInteraction },
      },
      legacy: true,
      scriptId: frame.scriptId,
    };
  }

  return null;
};

const selectionContextForElement = element => {
  const context = {
    type: element.type,
    id: element.id,
    x: Math.round(element.x || 0),
    y: Math.round(element.y || 0),
    w: Math.round(element.width || 0),
    h: Math.round(element.height || 0),
    points: element.points ? element.points.map(point => [Math.round(point[0]), Math.round(point[1])]) : undefined,
  };
  const codeHost = codeHostContextForElement(element);
  return codeHost ? { ...context, codeHost } : context;
};

const INITIAL_GREETING = "Hello! I am your drawing assistant powered by local AI. You can write prompts like \"draw a flow chart\", \"sketch a house\", or \"clear the canvas\" and I will execute the drawing tools programmatically!";

const THINKING_BRAILLE_FRAMES = Object.freeze(["⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"]);

function ThinkingIndicator() {
  const [frame, setFrame] = useState(0);
  const [motionAllowed, setMotionAllowed] = useState(true);

  useEffect(() => {
    const media = window.matchMedia?.("(prefers-reduced-motion: reduce)");
    if (!media) return undefined;
    const update = () => setMotionAllowed(!media.matches);
    update();
    media.addEventListener?.("change", update);
    return () => media.removeEventListener?.("change", update);
  }, []);

  useEffect(() => {
    if (!motionAllowed) {
      setFrame(0);
      return undefined;
    }
    const timer = window.setInterval(() => {
      setFrame(previous => (previous + 1) % THINKING_BRAILLE_FRAMES.length);
    }, 120);
    return () => window.clearInterval(timer);
  }, [motionAllowed]);

  return <span className="ai-thinking-indicator" role="status" aria-label="AI is thinking">
    <span>Thinking</span>
    <span className="ai-thinking-braille" aria-hidden="true">{THINKING_BRAILLE_FRAMES[frame]}</span>
  </span>;
}

const DRAWING_ROUNDNESS_STORAGE_KEY = "underscores_drawing_roundness";
const CUSTOM_BRUSH_ROUNDNESS_STORAGE_KEY = "underscores_custom_brush_roundness";
const readDrawingRoundness = () => {
  try {
    const stored = localStorage.getItem(DRAWING_ROUNDNESS_STORAGE_KEY)
      ?? localStorage.getItem(CUSTOM_BRUSH_ROUNDNESS_STORAGE_KEY);
    return stored === "1" || stored === "true";
  } catch {
    return false;
  }
};

const resolveMidiInputs = (access, portId) => {
  if (!access || portId === MIDI_PORT_NONE) return [];
  if (portId === MIDI_PORT_ALL) return [...access.inputs.values()];
  const input = access.inputs.get(portId);
  return input ? [input] : [];
};

function createBaseElement(type, x, y, width, height, strokeColor = "#f8fafc") {
  return {
    id: `${type}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    type,
    x,
    y,
    width,
    height,
    angle: 0,
    strokeColor,
    backgroundColor: "transparent",
    fillStyle: "hachure",
    strokeWidth: 2,
    strokeStyle: "solid",
    roughness: 0,
    opacity: 100,
    groupIds: [],
    frameId: null,
    roundness: null,
    seed: Math.floor(Math.random() * 1000000),
    version: 1,
    versionNonce: Math.floor(Math.random() * 1000000),
    isDeleted: false,
    boundElements: null,
    updated: Date.now(),
    link: null,
    locked: false
  };
}

const getCanonicalExportBounds = elements => {
  const activeElements = (elements || []).filter(element => element && !element.isDeleted);
  if (!activeElements.length) return null;
  const [minX, minY, maxX, maxY] = getCommonBounds(activeElements);
  if (![minX, minY, maxX, maxY].every(Number.isFinite)) return null;
  return { minX, minY, maxX, maxY };
};

const cropCanvasToSceneBounds = (sourceCanvas, sourceBounds, targetBounds, documentRef = globalThis.document) => {
  if (!sourceCanvas || !sourceBounds || !targetBounds || !documentRef?.createElement) return sourceCanvas;
  const sourceWidth = Math.max(1, sourceBounds.maxX - sourceBounds.minX);
  const sourceHeight = Math.max(1, sourceBounds.maxY - sourceBounds.minY);
  const targetWidth = Math.max(1, targetBounds.maxX - targetBounds.minX);
  const targetHeight = Math.max(1, targetBounds.maxY - targetBounds.minY);
  const scaleX = sourceCanvas.width / sourceWidth;
  const scaleY = sourceCanvas.height / sourceHeight;
  const output = documentRef.createElement("canvas");
  output.width = Math.max(1, Math.round(targetWidth * scaleX));
  output.height = Math.max(1, Math.round(targetHeight * scaleY));
  const context = output.getContext?.("2d");
  if (!context) return sourceCanvas;
  context.drawImage(
    sourceCanvas,
    (targetBounds.minX - sourceBounds.minX) * scaleX,
    (targetBounds.minY - sourceBounds.minY) * scaleY,
    targetWidth * scaleX,
    targetHeight * scaleY,
    0,
    0,
    output.width,
    output.height,
  );
  return output;
};

const getBakeExportPadding = elements => Math.max(2, ...(elements || []).map(element => {
  const strokeWidth = Number(element?.strokeWidth) || 1;
  const roughness = Number(element?.roughness) || 0;
  return Math.ceil(strokeWidth * (1 + roughness * 0.5));
}));

const isColorTransparent = (color) => {
  if (!color) return false;
  const c = color.trim().toLowerCase();
  if (c === "transparent") return true;
  if (c.startsWith("#") && c.length === 9 && c.endsWith("00")) return true;
  if (c.startsWith("#") && c.length === 5 && c.endsWith("0")) return true;
  if (c.startsWith("rgba")) {
    const parts = c.split(",");
    if (parts.length === 4) {
      const alpha = parseFloat(parts[3].replace(")", ""));
      return alpha === 0;
    }
  }
  return false;
};

const makeColorTransparent = (color) => {
  if (!color) return "transparent";
  const c = color.trim();
  const cLower = c.toLowerCase();
  if (cLower.startsWith("#")) {
    if (c.length === 7) return c + "00";
    if (c.length === 4) {
      const r = c[1], g = c[2], b = c[3];
      return `#${r}${r}${g}${g}${b}${b}00`;
    }
  } else if (cLower.startsWith("rgb(")) {
    return cLower.replace("rgb(", "rgba(").replace(")", ", 0)");
  }
  return "transparent";
};

const makeColorOpaque = (color, fallback) => {
  if (!color) return fallback;
  const c = color.trim();
  const cLower = c.toLowerCase();
  if (cLower === "transparent") return fallback;
  if (cLower.startsWith("#")) {
    if (c.length === 9 && cLower.endsWith("00")) {
      return c.slice(0, 7);
    }
    if (c.length === 5 && cLower.endsWith("0")) {
      return c.slice(0, 4);
    }
  } else if (cLower.startsWith("rgba(")) {
    const parts = c.split(",");
    if (parts.length === 4) {
      return parts.slice(0, 3).join(",").replace(/rgba\(/i, "rgb(") + ")";
    }
  }
  return fallback;
};

const CSS_COLOR_HELP = "Accepts CSS color values: hex (#rgb, #rrggbb, #rrggbbaa), named colors (red), rgb()/rgba(), hsl()/hsla(), hwb(), lab(), lch(), oklab(), and oklch(). The separate percentage multiplies the color's own alpha.";

// Keep the global interface choice deliberately small and local to fonts that
// are already shipped with the application (plus stable system fallbacks).
// Livecode node typography remains independently authored on each node.
const INTERFACE_FONT_OPTIONS = Object.freeze([
  Object.freeze({ id: "inter", label: "Inter", family: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }),
  Object.freeze({ id: "fira-mono", label: "Fira Mono", family: "'Fira Mono', ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, monospace" }),
  Object.freeze({ id: "system", label: "System sans", family: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }),
  Object.freeze({ id: "system-mono", label: "System mono", family: "ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, monospace" }),
]);

const getInterfaceFont = value => INTERFACE_FONT_OPTIONS.find(option => option.id === value) || INTERFACE_FONT_OPTIONS[0];

const DOCUMENTATION_TIP_MODES = Object.freeze([
  Object.freeze({ id: "none", label: "None" }),
  Object.freeze({ id: "hover", label: "Hover" }),
  Object.freeze({ id: "select", label: "Select" }),
]);

const normalizeDocumentationTipMode = value => DOCUMENTATION_TIP_MODES.some(option => option.id === value) ? value : "hover";

const resolveCssColor = color => {
  const source = String(color || "").trim();
  if (!source) return null;
  const shortHex = source.match(/^#([0-9a-f]{3,4})$/i);
  const longHex = source.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/i);
  if (shortHex || longHex) {
    const hex = (shortHex
      ? shortHex[1].split("").map(channel => channel + channel).join("")
      : `${longHex[1]}${longHex[2] || ""}`).toLowerCase();
    return {
      red: parseInt(hex.slice(0, 2), 16),
      green: parseInt(hex.slice(2, 4), 16),
      blue: parseInt(hex.slice(4, 6), 16),
      alpha: hex.length === 8 ? parseInt(hex.slice(6, 8), 16) / 255 : 1,
    };
  }
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d");
  if (!context) return null;
  const sentinel = "#010203";
  context.fillStyle = sentinel;
  context.fillStyle = source;
  const resolved = String(context.fillStyle || "");
  if (resolved === sentinel && source.toLowerCase() !== sentinel) return null;
  const match = resolved.match(/^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:\s*[,/]\s*([\d.]+))?\s*\)$/i);
  if (!match) return resolveCssColor(resolved);
  return {
    red: Math.round(Number(match[1])),
    green: Math.round(Number(match[2])),
    blue: Math.round(Number(match[3])),
    alpha: match[4] === undefined ? 1 : Math.min(1, Math.max(0, Number(match[4]))),
  };
};

const isCssColor = color => Boolean(resolveCssColor(color));

const colorInputHex = (color, fallback = "#000000") => {
  const resolved = resolveCssColor(color);
  if (!resolved) return fallback;
  return `#${[resolved.red, resolved.green, resolved.blue]
    .map(channel => Math.min(255, Math.max(0, channel)).toString(16).padStart(2, "0"))
    .join("")}`;
};

const rgbColor = (red, green, blue, alpha = 1) => {
  const channels = [red, green, blue].map(channel => Math.min(255, Math.max(0, Math.round(Number(channel) || 0))));
  const opacity = Math.min(1, Math.max(0, Number(alpha)));
  if (opacity >= 0.999) return `#${channels.map(channel => channel.toString(16).padStart(2, "0")).join("")}`;
  return `rgba(${channels.join(", ")}, ${opacity})`;
};

const colorFromValue = value => {
  const resolved = resolveCssColor(value);
  return resolved && resolved.alpha > 0.01
    ? rgbColor(resolved.red, resolved.green, resolved.blue, resolved.alpha)
    : null;
};

const sampleRenderedElementColor = element => {
  if (!element || typeof window === "undefined") return null;
  const style = window.getComputedStyle(element);
  const displayColor = color => color ? displaySampledColor(color, element) : null;
  const background = colorFromValue(style.backgroundColor);
  if (background) return displayColor(background);
  const border = style.borderTopStyle !== "none" && Number.parseFloat(style.borderTopWidth) > 0
    ? colorFromValue(style.borderTopColor)
    : null;
  if (border) return displayColor(border);
  const fill = style.fill && style.fill !== "none" ? colorFromValue(style.fill) : null;
  if (fill) return displayColor(fill);
  const stroke = style.stroke && style.stroke !== "none" ? colorFromValue(style.stroke) : null;
  if (stroke) return displayColor(stroke);
  return displayColor(colorFromValue(style.color));
};

const sampleAppColorAt = (clientX, clientY) => {
  if (typeof document === "undefined") return null;
  const elements = document.elementsFromPoint?.(clientX, clientY) || [];
  const canvases = [];
  const seenCanvases = new Set();
  for (const element of elements) {
    if (element?.tagName === "CANVAS" && !seenCanvases.has(element)) {
      seenCanvases.add(element);
      canvases.push(element);
    }
  }
  // Excalidraw keeps its static artwork beneath a transparent interactive
  // canvas, so it is not returned by elementsFromPoint even though it is the
  // layer carrying the visible pixels. Include every canvas whose bounds
  // contain the pointer, preserving the hit-tested canvases first.
  for (const canvas of document.querySelectorAll?.("canvas") || []) {
    if (seenCanvases.has(canvas)) continue;
    const rect = canvas.getBoundingClientRect();
    if (rect.width >= 2 && rect.height >= 2
      && clientX >= rect.left && clientY >= rect.top
      && clientX <= rect.right && clientY <= rect.bottom) {
      seenCanvases.add(canvas);
      canvases.push(canvas);
    }
  }
  for (const canvas of canvases) {
    const rect = canvas.getBoundingClientRect();
    if (rect.width < 2 || rect.height < 2 || clientX < rect.left || clientY < rect.top || clientX > rect.right || clientY > rect.bottom) continue;
    const pixelX = Math.min(canvas.width - 1, Math.max(0, Math.floor((clientX - rect.left) * canvas.width / rect.width)));
    const pixelY = Math.min(canvas.height - 1, Math.max(0, Math.floor((clientY - rect.top) * canvas.height / rect.height)));
    try {
      const context2d = canvas.getContext("2d", { willReadFrequently: true });
      const pixel = context2d?.getImageData(pixelX, pixelY, 1, 1).data;
      if (pixel && pixel[3] > 0) {
        return displaySampledColor(rgbColor(pixel[0], pixel[1], pixel[2], pixel[3] / 255), canvas);
      }
      const contextGl = canvas.getContext("webgl2") || canvas.getContext("webgl");
      if (contextGl) {
        const glPixel = new Uint8Array(4);
        contextGl.readPixels(pixelX, canvas.height - pixelY - 1, 1, 1, contextGl.RGBA, contextGl.UNSIGNED_BYTE, glPixel);
        if (glPixel[3] > 0) {
          return displaySampledColor(rgbColor(glPixel[0], glPixel[1], glPixel[2], glPixel[3] / 255), canvas);
        }
      }
    } catch {
      // Cross-origin or non-readable canvases are skipped in the fallback sampler.
    }
  }
  const seen = new Set();
  for (const element of elements) {
    let current = element;
    while (current && current !== document.documentElement) {
      if (!seen.has(current)) {
        seen.add(current);
        const sampled = sampleRenderedElementColor(current);
        if (sampled) return sampled;
      }
      current = current.parentElement;
    }
  }
  return null;
};

const rgbToHsv = ({ red = 0, green = 0, blue = 0, alpha = 1 }) => {
  const r = Math.min(1, Math.max(0, Number(red) / 255));
  const g = Math.min(1, Math.max(0, Number(green) / 255));
  const b = Math.min(1, Math.max(0, Number(blue) / 255));
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const delta = max - min;
  let hue = 0;
  if (delta > 0) {
    if (max === r) hue = 60 * (((g - b) / delta) % 6);
    else if (max === g) hue = 60 * ((b - r) / delta + 2);
    else hue = 60 * ((r - g) / delta + 4);
  }
  return {
    hue: (hue + 360) % 360,
    saturation: max === 0 ? 0 : delta / max,
    value: max,
    alpha: Math.min(1, Math.max(0, Number(alpha))),
  };
};

const hsvToRgb = (hue, saturation, value) => {
  const h = ((Number(hue) % 360) + 360) % 360;
  const s = Math.min(1, Math.max(0, Number(saturation)));
  const v = Math.min(1, Math.max(0, Number(value)));
  const chroma = v * s;
  const sector = h / 60;
  const x = chroma * (1 - Math.abs((sector % 2) - 1));
  const match = v - chroma;
  let red = 0;
  let green = 0;
  let blue = 0;
  if (sector < 1) [red, green, blue] = [chroma, x, 0];
  else if (sector < 2) [red, green, blue] = [x, chroma, 0];
  else if (sector < 3) [red, green, blue] = [0, chroma, x];
  else if (sector < 4) [red, green, blue] = [0, x, chroma];
  else if (sector < 5) [red, green, blue] = [x, 0, chroma];
  else [red, green, blue] = [chroma, 0, x];
  return {
    red: Math.round((red + match) * 255),
    green: Math.round((green + match) * 255),
    blue: Math.round((blue + match) * 255),
  };
};

const colorWithOpacity = (color, opacity) => {
  const resolved = resolveCssColor(color);
  if (!resolved) return color;
  const alpha = resolved.alpha * Math.min(100, Math.max(0, Number(opacity))) / 100;
  return `rgba(${resolved.red}, ${resolved.green}, ${resolved.blue}, ${alpha})`;
};

const colorWithAlpha = (color, alpha) => {
  const resolved = resolveCssColor(color);
  if (!resolved) return color;
  return rgbColor(resolved.red, resolved.green, resolved.blue, alpha);
};

// Excalidraw filters authored canvas marks in dark mode, while some overlays
// remain unfiltered. Convert authored canvas/overlay colors to what is
// actually visible on the board.
const canvasDisplayColor = (color, theme) => {
  const resolved = resolveCssColor(color);
  if (!resolved || theme !== "dark") return color;
  const invertAmount = 0.93;
  const inverted = [resolved.red, resolved.green, resolved.blue]
    .map(channel => invertAmount + (1 - 2 * invertAmount) * channel / 255);
  const hue180 = [
    [-0.574, 1.43, 0.144],
    [0.426, 0.43, 0.144],
    [0.426, 1.43, -0.856],
  ];
  const transformed = hue180.map(row => row.reduce(
    (sum, coefficient, index) => sum + coefficient * inverted[index],
    0,
  ));
  const [red, green, blue] = transformed.map(channel => Math.round(
    Math.min(1, Math.max(0, channel)) * 255,
  ));
  return `rgba(${red}, ${green}, ${blue}, ${resolved.alpha})`;
};

const hasExcalidrawDarkThemeFilter = element => {
  if (!element || typeof window === "undefined") return false;
  let current = element;
  while (current && current !== document.documentElement) {
    const filter = window.getComputedStyle(current).filter;
    if (filter && filter !== "none" && /invert\(/i.test(filter) && /hue-rotate\(\s*180deg/i.test(filter)) return true;
    current = current.parentElement;
  }
  return false;
};

const displaySampledColor = (color, element) => {
  if (!color || !hasExcalidrawDarkThemeFilter(element)) return color;
  return canvasDisplayColor(color, "dark");
};

const DEFAULT_LASER_COLOR = "#67d7e6";

const resolveLaserColorToken = (value, palette) => {
  const token = String(value || "").trim().toLowerCase();
  return palette[token] || value || DEFAULT_LASER_COLOR;
};

const formatScriptJsonParameter = value => {
  try {
    return JSON.stringify(value === undefined ? {} : value, null, 2);
  } catch {
    return "{}";
  }
};

const ScriptParameterEditor = ({ parameter, disabled = false, onChange, onPickObject, colorPreview, colorAppearance = {} }) => {
  const jsonFocusedRef = useRef(false);
  const colorFocusedRef = useRef(false);
  const colorPickerRef = useRef(null);
  const colorHsvRef = useRef(null);
  const colorAlphaRef = useRef(1);
  const eyedropperPreviewRef = useRef(null);
  const commitColorDraftRef = useRef(null);
  const [jsonDraft, setJsonDraft] = useState(() => formatScriptJsonParameter(parameter.value));
  const [colorDraft, setColorDraft] = useState(() => String(parameter.value ?? ""));
  const [colorPickerOpen, setColorPickerOpen] = useState(false);
  const [eyedropperActive, setEyedropperActive] = useState(false);
  const [eyedropperPreview, setEyedropperPreview] = useState(null);
  const [eyedropperTheme, setEyedropperTheme] = useState(null);
  const [colorHsv, setColorHsv] = useState(() => rgbToHsv(resolveCssColor(colorPreview ?? parameter.value) || {}));
  useEffect(() => {
    if (!jsonFocusedRef.current) setJsonDraft(formatScriptJsonParameter(parameter.value));
    if (!colorFocusedRef.current) setColorDraft(String(parameter.value ?? ""));
  }, [parameter.value]);
  useEffect(() => {
    if (!colorPickerOpen) return undefined;
    const handlePointerDown = event => {
      if (!colorPickerRef.current?.contains(event.target)) setColorPickerOpen(false);
    };
    const handleKeyDown = event => {
      if (event.key !== "Escape") return;
      setEyedropperActive(false);
      setColorPickerOpen(false);
      event.preventDefault();
      event.stopPropagation();
    };
    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [colorPickerOpen]);
  useEffect(() => {
    if (!eyedropperActive) {
      eyedropperPreviewRef.current = null;
      setEyedropperPreview(null);
      setEyedropperTheme(null);
      return undefined;
    }
    const themeScope = colorPickerRef.current || document.body;
    const themeStyles = window.getComputedStyle(themeScope);
    setEyedropperTheme({
      "--color-primary": themeStyles.getPropertyValue("--color-primary").trim() || "#fff",
      "--color-secondary": themeStyles.getPropertyValue("--color-secondary").trim() || "#bbb",
      "--underscores-panel-bg": themeStyles.getPropertyValue("--underscores-panel-bg").trim() || "#181818",
      "--border-color": themeStyles.getPropertyValue("--border-color").trim() || "#555",
    });
    const previousCursor = document.body.style.cursor;
    document.body.style.cursor = "crosshair";
    document.body.dataset.iannixEyedropper = "true";
    const handlePointerMove = event => {
      if (colorPickerRef.current?.contains(event.target)) {
        eyedropperPreviewRef.current = null;
        setEyedropperPreview(null);
        return;
      }
      const sampled = sampleAppColorAt(event.clientX, event.clientY);
      const nextPreview = sampled
        ? {
          x: Math.max(8, Math.min(window.innerWidth - 124, event.clientX + 16)),
          y: Math.max(8, Math.min(window.innerHeight - 42, event.clientY + 16)),
          color: sampled,
        }
        : null;
      eyedropperPreviewRef.current = nextPreview;
      setEyedropperPreview(nextPreview);
    };
    const handlePointerDown = event => {
      if (colorPickerRef.current?.contains(event.target)) return;
      const sampled = eyedropperPreviewRef.current?.color || sampleAppColorAt(event.clientX, event.clientY);
      if (sampled) {
        commitColorDraftRef.current?.(colorWithAlpha(sampled, colorAlphaRef.current));
        setColorPickerOpen(false);
      }
      setEyedropperActive(false);
      event.preventDefault();
      event.stopPropagation();
    };
    const handleKeyDown = event => {
      if (event.key !== "Escape") return;
      setEyedropperActive(false);
      setColorPickerOpen(false);
      event.preventDefault();
      event.stopPropagation();
    };
    document.addEventListener("pointermove", handlePointerMove, true);
    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown, true);
    return () => {
      document.removeEventListener("pointermove", handlePointerMove, true);
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown, true);
      document.body.style.cursor = previousCursor;
      delete document.body.dataset.iannixEyedropper;
      eyedropperPreviewRef.current = null;
      setEyedropperPreview(null);
      setEyedropperTheme(null);
    };
  }, [eyedropperActive]);
  const label = parameter.label || parameter.name;
  const type = parameter.type || "number";
  const resolvedColor = colorPreview ?? parameter.value;
  const parsedColor = type === "color"
    ? resolveCssColor(resolvedColor) || { red: 0, green: 0, blue: 0, alpha: 1 }
    : { red: 0, green: 0, blue: 0, alpha: 1 };
  const alphaPercent = Math.round(Math.min(1, Math.max(0, parsedColor.alpha ?? 1)) * 100);
  useEffect(() => {
    if (type !== "color") return;
    const nextHsv = rgbToHsv(resolveCssColor(resolvedColor) || {});
    colorHsvRef.current = nextHsv;
    colorAlphaRef.current = nextHsv.alpha;
    setColorHsv(nextHsv);
  }, [resolvedColor, type]);
  const excalidrawColors = colorAppearance.colors?.excalidraw || colorAppearance.excalidraw || {};
  const colorReferences = [
    { value: "__.currentColor", label: "Current stroke", color: colorAppearance.currentColor || excalidrawColors.foreground?.css },
    { value: "__.currentBackgroundColor", label: "Current fill", color: colorAppearance.currentBackgroundColor || excalidrawColors.background?.css },
    { value: "__.colors.excalidraw.foreground.css", label: "Excalidraw stroke", color: excalidrawColors.foreground?.css },
    { value: "__.colors.excalidraw.background.css", label: "Excalidraw fill", color: excalidrawColors.background?.css },
    ...["foreground", "accent", "highlight", "muted", "panel", "input", "timeline", "canvas"].map(key => ({
      value: `__.colors.${key}.css`,
      label: key,
      color: colorAppearance.colors?.[key]?.css,
    })),
  ].filter(option => option.color);
  colorAlphaRef.current = parsedColor.alpha ?? 1;
  colorHsvRef.current = colorHsv;
  const setPickerHsv = next => {
    colorHsvRef.current = next;
    setColorHsv(next);
  };
  const commitPickerHsv = next => {
    const rgb = hsvToRgb(next.hue, next.saturation, next.value);
    commitColorDraft(rgbColor(rgb.red, rgb.green, rgb.blue, colorAlphaRef.current));
  };
  const updatePickerFromPoint = (event, field) => {
    const rect = event.currentTarget.getBoundingClientRect();
    const position = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
    const vertical = Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height));
    const next = field === "hue"
      ? { ...colorHsvRef.current, hue: position * 360 }
      : { ...colorHsvRef.current, saturation: position, value: 1 - vertical };
    setPickerHsv(next);
    commitPickerHsv(next);
  };
  const startPickerDrag = (event, field) => {
    event.preventDefault();
    const target = event.currentTarget;
    const handleMove = moveEvent => updatePickerFromPoint(moveEvent, field);
    const handleUp = () => {
      target.removeEventListener("pointermove", handleMove);
      target.removeEventListener("pointerup", handleUp);
      target.removeEventListener("pointercancel", handleUp);
    };
    target.addEventListener("pointermove", handleMove);
    target.addEventListener("pointerup", handleUp, { once: true });
    target.addEventListener("pointercancel", handleUp, { once: true });
    target.setPointerCapture?.(event.pointerId);
    updatePickerFromPoint(event, field);
  };
  const commitColorDraft = value => {
    colorFocusedRef.current = false;
    setColorDraft(value);
    const nextColor = resolveCssColor(value);
    if (nextColor) {
      const nextHsv = rgbToHsv(nextColor);
      colorHsvRef.current = nextHsv;
      setColorHsv(nextHsv);
      colorAlphaRef.current = nextHsv.alpha;
    }
    onChange?.(value);
  };
  commitColorDraftRef.current = commitColorDraft;
  const beginColorPick = event => {
    if (!event?.altKey) {
      setEyedropperActive(active => !active);
      return;
    }
    const EyeDropperConstructor = typeof window !== "undefined" ? window.EyeDropper : undefined;
    if (typeof EyeDropperConstructor === "function" && typeof EyeDropperConstructor.prototype?.open === "function") {
      const picker = new EyeDropperConstructor();
      picker.open()
        .then(result => {
          if (result?.sRGBHex) commitColorDraft(colorWithAlpha(result.sRGBHex, colorAlphaRef.current));
        })
        .catch(() => {
          // Cancellation is a normal exit path for the native screen picker.
        });
      return;
    }
    setEyedropperActive(active => !active);
  };
  if (type === "object") {
    return (
      <div className="iannix-inline-action">
        <input
          className="custom-brush-param-input"
          type="text"
          value={String(parameter.value ?? "")}
          placeholder="Object id, label, or group"
          disabled={disabled}
          onChange={event => onChange?.(event.target.value)}
          aria-label={label + " (" + parameter.name + ")"}
        />
        {onPickObject && <button
          type="button"
          className="properties-object-picker"
          onClick={onPickObject}
          disabled={disabled}
          title={"Pick " + label + " from the canvas"}
          aria-label={"Pick " + label + " from the canvas"}
        >⌖</button>}
      </div>
    );
  }
  if (type === "color") {
    return (
      <div className="iannix-inline-action iannix-color-parameter">
        <div className="iannix-color-picker" ref={colorPickerRef}>
          <button
            type="button"
            className="iannix-color-swatch"
            style={{ "--iannix-color-value": resolvedColor || "transparent" }}
            disabled={disabled}
            onClick={() => setColorPickerOpen(open => !open)}
            aria-haspopup="dialog"
            aria-expanded={colorPickerOpen}
            aria-label={label + " color picker"}
            title="Choose color and alpha"
          />
          {colorPickerOpen && <div className="iannix-color-popover" role="dialog" aria-label={label + " color and alpha"}>
            <div
              className="iannix-color-sv-field"
              style={{ "--iannix-picker-hue": colorHsv.hue }}
              onPointerDown={event => startPickerDrag(event, "sv")}
              role="slider"
              aria-label={label + " saturation and brightness"}
              aria-valuetext={`${Math.round(colorHsv.saturation * 100)}% saturation, ${Math.round(colorHsv.value * 100)}% brightness`}
              tabIndex={0}
            >
              <span
                className="iannix-color-sv-thumb"
                style={{ left: `${colorHsv.saturation * 100}%`, top: `${(1 - colorHsv.value) * 100}%` }}
              />
            </div>
            <div
              className="iannix-color-hue-field"
              onPointerDown={event => startPickerDrag(event, "hue")}
              role="slider"
              aria-label={label + " hue"}
              aria-valuemin="0"
              aria-valuemax="360"
              aria-valuenow={Math.round(colorHsv.hue)}
              tabIndex={0}
            >
              <span className="iannix-color-hue-thumb" style={{ left: `${(colorHsv.hue / 360) * 100}%` }} />
            </div>
            <div className="iannix-color-popover-toolbar">
              <span className="iannix-color-readout" style={{ "--iannix-color-value": resolvedColor || "transparent" }} aria-hidden="true" />
              <button
                type="button"
                className="iannix-color-eyedropper"
                disabled={disabled}
                onClick={beginColorPick}
                aria-pressed={eyedropperActive}
                title={eyedropperActive ? "Move over the app to preview; click to sample (Escape cancels)" : "Pick an app color (Alt-click for screen)"}
                aria-label="Pick a color from the canvas"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <path d="m14 4 6 6" /><path d="m12 6 6 6" /><path d="m5 19 5-5" /><path d="m4 20 1-4L16 5l4 4-11 11-5 1Z" />
                </svg>
              </button>
              <button
                type="button"
                className="iannix-color-transparent"
                disabled={disabled}
                onClick={() => commitColorDraft("transparent")}
                aria-pressed={colorDraft === "transparent"}
                title="Use transparent"
                aria-label="Use transparent"
              >None</button>
              <output>{eyedropperActive
                ? (eyedropperPreview ? colorInputHex(eyedropperPreview.color) : "Move to canvas")
                : `${colorInputHex(resolvedColor)} · ${alphaPercent}%`}</output>
            </div>
            {colorReferences.length > 0 && <div className="iannix-color-reference-section">
              <span className="iannix-color-reference-title">__ colors</span>
              <div className="iannix-color-reference-grid">
                {colorReferences.map(option => <button
                  type="button"
                  key={option.value}
                  className="iannix-color-reference"
                  onClick={() => commitColorDraft(option.value)}
                  aria-pressed={colorDraft === option.value}
                  title={option.value}
                  aria-label={`Use ${option.label} color (${option.value})`}
                >
                  <span className="iannix-color-reference-swatch" style={{ "--iannix-color-value": option.color }} />
                  <span>{option.label}</span>
                </button>)}
              </div>
            </div>}
            <label className="iannix-color-alpha-field">
              <span>Alpha</span>
              <input
                type="range"
                min="0"
                max="100"
                step="1"
                value={alphaPercent}
                disabled={disabled}
                onChange={event => commitColorDraft(colorWithAlpha(resolvedColor, Number(event.target.value) / 100))}
                aria-label={label + " alpha"}
              />
              <output>{alphaPercent}%</output>
            </label>
          </div>}
        </div>
        {eyedropperActive && eyedropperPreview && createPortal(
          <div
            className="iannix-eyedropper-preview"
            style={{ left: eyedropperPreview.x, top: eyedropperPreview.y, ...eyedropperTheme }}
            role="status"
            aria-live="polite"
          >
            <span
              className="iannix-eyedropper-preview-swatch"
              style={{ "--iannix-color-value": eyedropperPreview.color }}
              aria-hidden="true"
            />
            <code>{colorInputHex(eyedropperPreview.color)}</code>
          </div>,
          document.body,
        )}
        <input
          className="custom-brush-param-input"
          type="text"
          value={colorDraft}
          disabled={disabled}
          onFocus={() => { colorFocusedRef.current = true; }}
          onChange={event => setColorDraft(event.target.value)}
          onBlur={() => {
            if (colorFocusedRef.current) commitColorDraft(colorDraft);
          }}
          onKeyDown={event => {
            if (event.key === "Enter") {
              event.preventDefault();
              commitColorDraft(colorDraft);
              event.currentTarget.blur();
            }
          }}
          aria-label={label + " color value"}
        />
      </div>
    );
  }
  if (type === "string") {
    return <input
      className="custom-brush-param-input"
      type="text"
      value={String(parameter.value ?? "")}
      disabled={disabled}
      onChange={event => onChange?.(event.target.value)}
      aria-label={label + " (" + parameter.name + ")"}
    />;
  }
  if (type === "json") {
    return <textarea
      className="custom-brush-param-input iannix-json-param-input"
      value={jsonDraft}
      disabled={disabled}
      onFocus={() => { jsonFocusedRef.current = true; }}
      onChange={event => setJsonDraft(event.target.value)}
      onBlur={() => {
        jsonFocusedRef.current = false;
        try {
          onChange?.(JSON.parse(jsonDraft));
        } catch {
          // Keep invalid JSON in the editor so it can be corrected without
          // replacing the last valid value used by the running script.
        }
      }}
      aria-label={label + " JSON"}
      spellCheck="false"
    />;
  }
  if (type === "boolean") {
    return <input
      type="checkbox"
      checked={normalizeScriptParameterValue(parameter, parameter.value)}
      disabled={disabled}
      onChange={event => onChange?.(event.target.checked)}
      aria-label={label + " (" + parameter.name + ")"}
    />;
  }
  return <NumericInput
    className="custom-brush-param-input"
    min={parameter.min}
    max={parameter.max}
    step={parameter.step}
    data-default={parameter.default}
    value={parameter.value}
    defaultValue={parameter.default ?? parameter.value}
    disabled={disabled}
    onCommit={onChange}
    aria-label={label + " (" + parameter.name + ")"}
  />;
};

const laserCursorForColor = color => {
  const resolved = resolveCssColor(color) || { red: 103, green: 215, blue: 230 };
  const stroke = `rgba(${resolved.red}, ${resolved.green}, ${resolved.blue}, ${resolved.alpha ?? 1})`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="7" fill="none" stroke="${stroke}" stroke-width="1.35"/><circle cx="12" cy="12" r="2.25" fill="${stroke}"/></svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}") 12 12, crosshair`;
};

// Excalidraw filters its entire drawing canvas in dark mode. Pre-transform the
// authored canvas color so the visible result still matches the theme swatch.
const canvasColorForExcalidraw = (color, opacity, theme) => {
  const resolved = resolveCssColor(color);
  if (!resolved) return color;
  const alpha = resolved.alpha * Math.min(100, Math.max(0, Number(opacity)));
  if (theme !== "dark") return `rgba(${resolved.red}, ${resolved.green}, ${resolved.blue}, ${alpha / 100})`;
  const desired = [resolved.red, resolved.green, resolved.blue].map(channel => channel / 255);
  const invertAmount = 0.93;
  const invertScale = 1 - 2 * invertAmount;
  const beforeHue = desired.map(channel => (channel - invertAmount) / invertScale);
  const hue180 = [
    [-0.574, 1.43, 0.144],
    [0.426, 0.43, 0.144],
    [0.426, 1.43, -0.856],
  ];
  const source = hue180.map(row => row.reduce((sum, coefficient, index) => sum + coefficient * beforeHue[index], 0));
  const channels = source.map(channel => Math.round(Math.min(1, Math.max(0, channel)) * 255));
  return `rgba(${channels.join(", ")}, ${alpha / 100})`;
};

const DEFAULT_ROLE_THEME = {
  // Authored colour is the normal score appearance. This palette is an
  // explicit role override, useful for score visualisation but never a reason
  // to discard a script's setColor/setColorHue decision.
  enabled: false,
  curveActive: { color: "#c9cdd2", opacity: 100 },
  curveInactive: { color: "#888888", opacity: 35 },
  cursorActive: { color: "#ff3b0a", opacity: 100 },
  cursorInactive: { color: "#888888", opacity: 35 },
  triggerActive: { color: "#00b8e8", opacity: 100 },
  triggerInactive: { color: "#888888", opacity: 35 },
  triggerPulse: { color: "#ff8a3d", opacity: 85 },
};

const normalizeThemeColorToken = (value, fallback) => {
  const source = value && typeof value === "object" ? value : {};
  return {
    color: isCssColor(source.color) ? String(source.color).trim() : fallback.color,
    opacity: Number.isFinite(Number(source.opacity))
      ? Math.min(100, Math.max(0, Number(source.opacity)))
      : fallback.opacity,
  };
};

const normalizeRoleTheme = value => {
  const saved = value && typeof value === "object" ? value : {};
  const next = { ...DEFAULT_ROLE_THEME, ...saved };
  // Migrate the old built-in dark curve swatch. Preserve any other custom
  // role choices; this only repairs the exact legacy default that makes a
  // score effectively disappear against Mono Dark.
  if (saved.enabled === true && String(saved.curveActive?.color || "").toLowerCase() === "#333333" && Number(saved.curveActive?.opacity) === 100) {
    next.curveActive = { ...DEFAULT_ROLE_THEME.curveActive };
  }
  return next;
};

