const DEFAULT_INTERFACE_THEME_PRESET = "monoDark";
const CUSTOM_THEME_STORAGE_KEY = "underscores_custom_themes_v1";
const PHYSICS_DEBUG_STORAGE_KEY = "underscores_physics_debug_v1";
const PHYSICS_TIME_SCRUB_STORAGE_KEY = "underscores_physics_time_scrub_v1";
// Version the preference so boards created before the closed-by-default
// layout do not inherit their old implicit `true` value on first launch.
const PHYSICS_TOOLBAR_OPEN_STORAGE_KEY = "underscores_physics_toolbar_open_v2";
const PHYSICS_TOOLBAR_DOCKED_STORAGE_KEY = "underscores_physics_toolbar_docked";
const INTERNAL_SYNTH_RESTORE_STORAGE_KEY = "underscores_internal_synth_restore";
const DEFAULT_PHYSICS_DEBUG_COLORS = Object.freeze({
  bodies: "#518effe6",
  colliders: "#61d5b1f2",
  constraints: "#ffbe50f2",
  labels: "#6db7ffff",
  contacts: "#61d5b1ff",
  collisions: "#ff7867ff",
  forces: "#ffd05eff",
});
const DEFAULT_PHYSICS_DEBUG = Object.freeze({
  enabled: false,
  bodies: true,
  colliders: true,
  constraints: true,
  labels: false,
  contacts: true,
  collisions: true,
  forces: true,
  trails: false,
});
const normalizePhysicsDebugColor = (value, fallback) => {
  const candidate = String(value || "").trim();
  if (candidate.toLowerCase() === "object") return "object";
  if (/^#[0-9a-f]{6}$/i.test(candidate)) return `${candidate.toLowerCase()}ff`;
  if (/^#[0-9a-f]{8}$/i.test(candidate)) return candidate.toLowerCase();
  if (isCssColor(candidate)) return candidate;
  return fallback;
};
const normalizePhysicsDebug = value => {
  const source = value && typeof value === "object" ? value : {};
  return {
    ...DEFAULT_PHYSICS_DEBUG,
    ...source,
    colors: Object.fromEntries(Object.entries(DEFAULT_PHYSICS_DEBUG_COLORS).map(([key, fallback]) => [key, normalizePhysicsDebugColor(source.colors?.[key], fallback)])),
    enabled: source.enabled === true,
  };
};
const normalizeCustomThemes = value => {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return Object.fromEntries(Object.entries(value).flatMap(([id, preset]) => {
    if (!preset || typeof preset !== "object" || !["light", "dark"].includes(preset.theme)) return [];
    const label = String(preset.label || "").trim();
    if (!label) return [];
    return [[id, {
      label,
      theme: preset.theme,
      accent: {
        color: isCssColor(preset.accent?.color) ? String(preset.accent.color).trim() : "#6b7173",
        opacity: Math.min(100, Math.max(0, Number(preset.accent?.opacity) || 0)),
      },
      highlight: {
        color: isCssColor(preset.highlight?.color) ? String(preset.highlight.color).trim() : "#8f9698",
        opacity: Math.min(100, Math.max(0, Number(preset.highlight?.opacity) || 0)),
      },
      foreground: normalizeThemeColorToken(preset.foreground, INTERFACE_THEME_PRESETS[preset.theme === "light" ? "underscoresLight" : "underscoresDark"].foreground),
      muted: normalizeThemeColorToken(preset.muted, INTERFACE_THEME_PRESETS[preset.theme === "light" ? "underscoresLight" : "underscoresDark"].muted),
      surfaces: normalizeInterfaceTheme(preset.surfaces, preset.theme),
      roleTheme: normalizeRoleTheme(preset.roleTheme),
    }]];
  }));
};

const normalizeInterfaceTheme = (value, theme = "dark") => {
  const fallback = INTERFACE_THEME_PRESETS[theme === "light" ? "underscoresLight" : "underscoresDark"].surfaces;
  const source = value && typeof value === "object" ? value : {};
  return Object.fromEntries(["panel", "input", "timeline", "canvas", "grid"].map(key => {
    const entry = source[key] && typeof source[key] === "object" ? source[key] : {};
    return [key, {
      color: isCssColor(entry.color) ? String(entry.color).trim() : fallback[key].color,
      opacity: Number.isFinite(Number(entry.opacity)) ? Math.min(100, Math.max(0, Number(entry.opacity))) : fallback[key].opacity,
    }];
  }));
};

